#!/usr/bin/env bash
# Golden values for GrammarUtility, generated by running the ORIGINAL Java class
# (from reference/columnal; see scripts/fetch-reference.sh) on tricky inputs.
# Usage: scripts/golden/grammar-utility.sh   (needs Java 17+)
# Output strings are printed as UTF-16 code units in hex, to avoid any encoding issues.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
{
cat <<'JAVA'
import java.util.*;
public class Harness {
    static String hex(String s) {
        StringJoiner j = new StringJoiner(" ");
        for (char c : s.toCharArray()) j.add(Integer.toHexString(c));
        return "[" + j + "]";
    }
    static String run(java.util.function.Supplier<Object> f) {
        try { Object o = f.get(); return o instanceof String s ? hex(s) : String.valueOf(o); }
        catch (Exception e) { return "EXCEPTION " + e.getClass().getSimpleName(); }
    }
    public static void main(String[] args) {
        String[] inputs = {
            "\"\"", "\"abc\"", "\"a^qb^nc^rd^te^cf^ag\"", "\"^\"", "\"x^\"", "\"^z\"", "\"^{41}\"", "\"^{ 41 }\"",
            "\"^{1F600}\"", "\"^{zz}\"", "\"^{41\"", "\"^{-41}\"", "\"^{+41}\"", "\"^{110000}\"", "\"^{D83D}^{DE00}\"",
            "\"😀 emoji\"", "\"^{}\"", "\"^{FFFFFFFFF}\"",
        };
        for (String in : inputs) {
            System.out.println("processEscapes " + hex(in) + " = " + run(() -> GrammarUtility.processEscapes(in)));
            System.out.println("processEscapesUnquoted " + hex(in) + " = " + run(() -> GrammarUtility.processEscapes(in, false)));
        }
        String[] words = {
            "", "a", "a00", "0aa", "a+0", "a a", "a  a", "a ", " a", "true", "false", "True", "a_b", "_a", "été",
            "١٢", "a١", "中文", "😀", "a😀", "Ⅰ", "aⅠ", "ª", "a²",
            "x́", "́x",
        };
        for (String w : words) {
            System.out.println("validUnquoted " + hex(w) + " = " + GrammarUtility.validUnquoted(w));
            System.out.println("validIdentifier " + hex(w) + " = " + GrammarUtility.validIdentifier(w));
        }
        String[] texts = {
            "", "plain", "^\"\n\r@", "a^^b", "  lots   of\tspace\n\n here  ", " nbsp ", "\u0085next\u0085",
            "\u0001ctrl\u0001", " em space", "﻿bom", "　ideographic　",
        };
        for (String t : texts) {
            System.out.println("escapeChars " + hex(t) + " = " + hex(GrammarUtility.escapeChars(t)));
            System.out.println("collapseSpaces " + hex(t) + " = " + hex(GrammarUtility.collapseSpaces(t)));
        }
    }
}
JAVA
sed -e 's/^package .*;//' -e 's/^public class GrammarUtility/class GrammarUtility/' "$ROOT/reference/columnal/parsers/src/main/java/xyz/columnal/grammar/GrammarUtility.java"
} > "$TMP/Harness.java"
java "$TMP/Harness.java"
